# Extract prices for the requested equipment
price_data = {
    "Ergonomic Office Chair (Herman Miller)": 1195,
    "Standing Desk (Electric Adjustable)": 649,
    "Meeting Table": 899,
    "HP WorkStation": 1499,
    "Wireless Mouse": 69,
    "Wireless Keyboard": 99
}

# Equipment requests from team members
requests = {
    "Li Ming": {
        "Ergonomic Office Chair (Herman Miller)": 5,
        "Standing Desk (Electric Adjustable)": 5
    },
    "Zhang Wei": {
        "Meeting Table": 3
    },
    "Huang Jie": {
        "HP WorkStation": 3,
        "Wireless Mouse": 3
    },
    "Sophia Rodriguez": {
        "Wireless Keyboard": 3
    }
}

# Calculate total budget
total_budget = 0
department_totals = {}

print("EQUIPMENT BUDGET CALCULATION")
print("=" * 60)

for person, equipment in requests.items():
    print(f"\n{person}:")
    person_total = 0
    for item, quantity in equipment.items():
        price = price_data[item]
        item_total = price * quantity
        person_total += item_total
        print(f"  - {item}: {quantity} × ${price} = ${item_total}")

    print(f"  Total for {person}: ${person_total}")

    # Group by department
    if person in ["Li Ming", "Zhang Wei"]:
        dept = "Database Department"
    else:
        dept = "Product Department"

    if dept not in department_totals:
        department_totals[dept] = 0
    department_totals[dept] += person_total

    total_budget += person_total

print("\n" + "=" * 60)
print("DEPARTMENT TOTALS:")
for dept, total in department_totals.items():
    print(f"  {dept}: ${total}")

print(f"\nTOTAL BUDGET REQUIRED: ${total_budget}")

